"""Write the 40 Studio One prompt files for the local LTX-2.5 pipeline.

LTX lessons applied: lead with the look, describe only what is seen (never name an
unwanted thing, even negated), one locked camera, a short Audio line so the native
audio stays as room tone instead of inventing speech.
"""
import os

W = os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompts")
os.makedirs(W, exist_ok=True)

# "newsreel" made LTX pillarbox the frame to 4:3; "full 16:9 frame" keeps it widescreen
# Any period date ("1938", "newsreel") made LTX pillarbox to 4:3, so the era lives in the objects
LOOK = ("Anamorphic widescreen cinematography, the image fills the whole frame from edge to edge. "
        "Black and white silver-gelatin look, heavy film grain, halation on lamps, charcoal blacks, "
        "ivory highlights, art deco period objects. ")
LOOK_RED = ("Anamorphic widescreen cinematography, the image fills the whole frame from edge to edge. "
            "Black and white silver-gelatin look except for one red pencil mark, heavy film grain, "
            "charcoal blacks, ivory highlights, art deco period objects. ")
CAM = " Locked camera, no camera movement. "
AUD = "Audio: faint room tone and a low hum."

P = {
# Deck 1 - Studio One
"s1_1_1_8pm_air": (LOOK, "A studio wall clock seen from directly below, lens almost touching the glass, the dial centred, twelve numerals as a ring of light, a single bulb above throwing concentric halo rings onto the glass.", "The second hand sweeps thirty degrees at a constant rate; the halo rings breathe slightly.", AUD),
"s1_1_2_roll_it": (LOOK, "A transcription lathe from straight above, a sixteen-inch acetate disc filling the frame, the groove a tight spiral of constant pitch, the cutting head on a radial arm, one lamp from the side.", "The disc turns steadily at thirty-three rpm and one thread of acetate curls off the cutting head in a growing helix.", AUD),
"s1_1_3_facing_mics": (LOOK, "An RCA 44-BX ribbon microphone seen through its own hexagonal wire grille from behind: two layers of hexagonal mesh slightly rotated against each other produce slow rolling moire fringes, and a single practical lamp beyond blooms as a soft glow through the diamond-shaped outline. Plain unmarked metal.", "The rear mesh turns one degree over the clip so the fringes drift one fringe-width.", "Audio: faint studio room tone and a low electrical hum."),
"s1_1_4_foley_table": (LOOK, "Looking straight down into a cast-iron pot of black water, a jam-jar lid resting on the rim, one lamp from the upper left.", "The lid scrapes a quarter of the rim every second and a half with a sinusoidal speed; each scrape launches rings across the water that interfere and fade in two seconds.", "Audio: metal scraping iron, water lapping."),
"s1_1_5_giant_cube": (LOOK, "Nine small electric motors in a three-by-three lattice on a workbench, seen from the bench end so the lattice collapses to one-point perspective, shafts as nine spinning discs, a work lamp above.", "The nine shafts spin at nine slightly different speeds; halfway through, a flashgun fires once and freezes them for one frame.", "Audio: nine motors whining at different pitches, one flashbulb pop."),
"s1_1_6_orchestra": (LOOK, "Twenty-seven music stands seen from a catwalk straight down, arranged in three concentric arcs of nine around a single point, white sheet music as rectangles on each stand, a double-height room in shadow around them.", "A page-turn ripple travels outward from the centre arc to the outer arc with ease-out, then repeats.", "Audio: pages turning, a hall's hush."),
"s1_1_7_the_glass": (LOOK, "A control-booth window at a twenty-degree dutch tilt, the booth lit amber behind the glass, two VU meter needles reflected in the pane, the reflection doubled by the glass thickness into two offset images.", "The needles swing on a three-to-two Lissajous figure with a two-and-a-half second period; the double image drifts apart one percent and back.", AUD),
"s1_1_8_dead_air": (LOOK, "One microphone on a stand in an empty studio, seen across the linoleum from floor level so the floor seams converge to a single vanishing point behind the stand, a lamp cone enclosing the stand.", "Dust falls through the lamp cone at a constant slow rate with a slight random jitter; nothing else moves.", "Audio: near silence, a faint hiss."),

# Deck 2 - Grovers Mill
"s1_2_1_observatory": (LOOK, "Inside an observatory dome looking up the telescope tube to the open slit, the dome's ribs as meridians converging at the zenith, the slit a narrow sector, a small bright disc crossing the slit.", "The dome rotates ten degrees with ease-in-out; the bright disc crosses the slit on a straight line at constant speed.", "Audio: dome motor grinding, wind."),
"s1_2_2_the_farm": (LOOK, "Two car headlight discs at a farm gate at night, each a soft glowing blob, their beams two cones crossing at the lens, crowd silhouettes as a picket of verticals at irregular spacing, camera at waist height inside the crowd, breath in the beams.", "The two headlight blobs merge and separate slowly as the cars rock; breath plumes rise and dissolve in two seconds.", "Audio: idling engines, murmuring crowd."),
"s1_2_3_the_hum": (LOOK, "A buried metal cylinder seen end-on from the pit floor, its ribs as rings receding to a vanishing point just above centre, each ring a fixed fraction smaller than the last, one work lamp from the side.", "A standing wave with three nodes shivers along the ribs with a period of one and a quarter seconds; the vanishing point does not move.", "Audio: a deep metallic hum."),
"s1_2_4_the_cap": (LOOK, "The round cap of a buried metal cylinder from directly above in a dark pit, a screw thread of ten concentric turns, one work lamp from the left so each turn is half lit.", "The cap rotates ninety degrees clockwise over four seconds with cubic ease-in, then stops dead; metal flakes shed along the tangent at the stop.", "Audio: grinding metal, then silence."),
"s1_2_5_emergence": (LOOK, "From under the rim of a pit, a wet ribbed tentacle unrolling as a logarithmic spiral, each turn larger than the last, lit by a stuttering flashlight, never fully in frame.", "The spiral unrolls one full turn with ease-out; the flashlight stutters four times a second.", "Audio: wet creaking, a flashlight clicking."),
"s1_2_6_heat_ray": (LOOK, "A single beam from a parabolic mirror as a horizontal line through the exact centre of the frame, seen from a ditch so the field is a plane below the line, headlights spaced along it at increasing distance.", "The beam sweeps forty degrees at constant angular rate and the headlights go out one by one in order of distance, one every half second.", "Audio: a rising electric whine, a low thud per light."),
"s1_2_7_field_lost": (LOOK, "A black field at night, one microphone cable lying as a catenary curve across wet grass in the foreground, a dropped flashlight the only light.", "The flashlight rolls in a damped arc, three swings each half the last, settling at four seconds; then stillness.", "Audio: a flashlight rolling on grass, then nothing."),
"s1_2_8_forty_dead": (LOOK, "A dry-stone wall seen along its length at ground level, the courses as parallel lines to a vanishing point at frame right, embers glowing behind it, black smoke as a turbulent sheet.", "The smoke moves left to right at a steady rate with rolling curls; the embers flicker at random.", "Audio: embers crackling, wind."),

# Deck 3 - The Visitors
"s1_3_1_the_curb": (LOOK, "A black 1938 sedan at a wet curb seen from the gutter looking up, the body one dark ellipse, its mirror reflection in the water below, two hat brims as two arcs passing above the lens, rain as vertical streaks in a street-lamp cone.", "Rain falls at constant speed; the reflection shimmers with a two-percent ripple; the brims pass left to right at walking pace.", "Audio: rain on pavement, two sets of footsteps."),
"s1_3_2_the_lobby": (LOOK, "A brass revolving door in an office lobby from directly above its hub, four glass leaves at ninety degrees forming a cross, the marble floor as radial sectors, a lift floor-dial arc reflected in the brass.", "The door turns exactly ninety degrees with ease-in-out so the frame ends as it began; the dial needle sweeps thirty degrees and back.", "Audio: a revolving door's rubber sweep, a lift bell."),
"s1_3_3_the_card": (LOOK_RED, "A plain white card on a desk in extreme macro, a three-by-two rectangle filling the frame, lamp light from the left.", "A red pencil line is drawn corner to corner along the diagonal at constant speed with a slight hand tremor.", "Audio: pencil on card."),
"s1_3_4_the_latch": (LOOK, "A studio door's round porthole window from the corridor side, a circle centred in frame, a console's glow a second concentric circle inside it, a ring of keys hanging across the chord. Low angle.", "The keys swing as a simple pendulum with a two-and-a-half second period and fifteen-degree amplitude, two full swings.", "Audio: keys jingling, a muffled hum."),
"s1_3_5_gloves_off": (LOOK, "A patch bay from six inches away, a twelve-by-eight grid of jacks, cords hanging in catenaries between them, one bare ridged hand resting on the grid, fingers as five parallels, knuckles only.", "The hand enters from the right over two seconds with ease-out and rests; the cords sway faintly from the touch.", AUD),
"s1_3_6_red_line": (LOOK_RED, "A typed script page in macro, the lines of type a ruled grid at constant leading, lamp light from above.", "A red pencil draws one straight line through one sentence from left to right over four seconds, then holds.", "Audio: pencil on paper."),
"s1_3_7_station_break": (LOOK_RED, "An RCA ribbon microphone seen from the announcer's chair tilted up thirty degrees, the grille a rhombus centred in frame, plain unmarked metal, one thin red horizontal line floating in the lamp glass behind it at the rhombus's horizontal diagonal.", "The red line pulses in brightness on a two-and-a-half second sine; the lamp halo breathes in antiphase.", AUD),
"s1_3_8_clock_held": (LOOK, "A studio clock reflected in a dark window, the second hand stopped at forty-one minutes past, the reflection doubled by the pane into two circles two percent apart in scale.", "The hands do not move; the two reflections drift half a percent apart and back on a five-second sine; the grain is the only other motion.", "Audio: silence with a faint tick that has stopped."),

# Deck 4 - New York
"s1_4_1_the_battery": (LOOK, "Artillery on a ridge at night seen from behind the crew at knee height, five barrels as parallel lines at fifteen degrees elevation, a tall three-legged shape on the horizon as an isosceles triangle.", "Muzzle flashes fire left to right, one every half second, each a single bright frame with half a second of smoke; the triangle takes one step toward the camera at four seconds.", "Audio: artillery firing in sequence, a distant metallic footfall."),
"s1_4_2_bombers": (LOOK, "Nine bombers in a V formation seen from directly below through low cloud, each propeller a spinning disc with a three-blade stroboscopic ghost, smoke rising past them in laminar sheets.", "The formation crosses the frame bottom to top at constant speed; the propeller ghosts reverse direction once at the midpoint; the smoke rises at half the formation's speed.", "Audio: nine radial engines droning."),
"s1_4_3_the_dive": (LOOK, "Inside a bomber's glazed nose, the glazing a lattice of ribs converging on one vanishing point dead ahead, a dark machine at that point.", "The dark machine grows exponentially by a factor of four over the clip as the ribs rush outward at the matching rate; straight dive, no roll.", "Audio: engines screaming, wind rising."),
"s1_4_4_the_roof": (LOOK, "The Manhattan skyline at night from a rooftop over the parapet edge, the skyline a jagged line scape in three parallax layers, a front of black smoke rolling across the Hudson toward the camera, lit from below by fires.", "The three layers drift right at one, two and three percent of frame; the smoke front advances toward the camera with eddies turning slowly.", "Audio: distant sirens, wind over the parapet."),
"s1_4_5_black_smoke": (LOOK, "Inside black smoke, the whole frame a slowly churning noise field, one street lamp a soft round halo at the exact centre.", "The field churns with curling motion on a two-and-a-half second period; the halo radius pulses ten percent on a five-second sine; nothing resolves.", "Audio: a muffled roar, nothing distinct."),
"s1_4_6_the_window": (LOOK, "A tall studio window at night seen from the sill looking down, the mullions a two-by-six grid, rain tracks as curved paths on the glass, the avenue below a receding column of glowing shop-window blobs at diminishing intervals.", "Rain tracks descend one pane-height every two and a half seconds with a random lateral walk; the shop windows flicker independently.", "Audio: rain on glass, a street far below."),
"s1_4_7_nineteen": (LOOK, "Nineteen tall three-legged machines standing in a park at dawn seen from the ground through bare trees, spaced on a hexagonal lattice to the horizon, black birds as a flock in a ring above them.", "The machines stand still; the ring of birds rotates once about a vertical axis, the birds merging at the near side of the ring.", "Audio: birds wheeling and crying, dawn wind."),
"s1_4_8_peaceful_study": (LOOK, "A desk lamp over a stack of books and a fountain pen writing, seen from inside a bookshelf between two volumes so the frame is a narrow vertical slot, book spines as horizontal bands top and bottom.", "The pen writes one line left to right over four seconds with a fine tremor, lifts and returns.", "Audio: a nib on paper, a clock ticking."),

# Deck 5 - Morning After
"s1_5_1_9pm_doors": (LOOK, "Heavy double doors opening toward the lens seen from floor level, each door edge sweeping a ninety-degree arc, dark uniforms in silhouette as a row of equal verticals behind, one flashbulb at frame centre.", "The doors open over two seconds with ease-out and hold; the flashbulb fires once at two seconds and its smoke rises for the rest of the clip.", "Audio: doors banging open, a flashbulb pop, boots."),
"s1_5_2_switchboard": (LOOK, "A telephone switchboard seen from straight above, a twenty-by-twelve grid of small lamps, cords hanging in catenaries, operators as hands only.", "The lamps light along a diagonal wavefront from top-left to bottom-right so the last lamp lights as the clip ends.", "Audio: hundreds of switchboard clicks and a rising buzz."),
"s1_5_3_flashbulbs": (LOOK, "Eleven press microphones clustered on a table at a press conference, seen from the table surface so they form a comb of equally spaced verticals, flashbulbs at random positions around the room.", "Flashbulbs fire at random about twice a second, each a single bright frame then half a second of smoke; the microphone shadows swing with each flash.", "Audio: flashbulbs popping, a murmuring press room."),
"s1_5_4_headlines": (LOOK, "A newspaper front page seen through the press rollers, eight columns as parallel verticals, the halftone dot screen visible as a forty-five degree lattice in macro, the type a grey texture.", "The page moves upward at exactly one page-height over the clip at constant speed.", "Audio: a printing press thundering."),
"s1_5_5_two_percent": (LOOK, "A rooftop of one hundred radio aerials at night in a staggered grid, rain falling, only two aerials with any light at their base.", "The two lit bases flicker independently; rain falls at constant speed; nothing else moves.", "Audio: rain on tin, a faint radio."),
"s1_5_6_hooper_vs_myth": (LOOK, "A stack of newspapers under a lamp seen from the end of the desk at paper height so the stack is a set of horizontal lines, a ruler laid across them as one diagonal.", "Dust settles through the lamp cone at constant speed; the lamp filament breathes five percent on a two-and-a-half second sine.", AUD),
"s1_5_7_the_disc": (LOOK, "A transcription disc in a rehearsal rack seen through the rack slats, the slats as vertical bars at equal spacing, the disc an arc behind them, a small paper circle on its sleeve catching the lamp as the one bright point.", "The disc rotates a quarter turn with ease-in-out so the paper circle passes behind exactly two slats and back.", "Audio: a rack creaking, a faint hum."),
"s1_5_8_next_week": (LOOK_RED, "A fresh script cover on a desk in macro, the page a rectangle filling the frame, one short red pencil mark as a diagonal in the upper-left quadrant, a lamp above.", "The lamp dims to black over the last two seconds with ease-in.", "Audio: a lamp switch, then silence."),
}

for name, (look, construction, motion, audio) in P.items():
    text = look + construction + CAM + motion + " " + audio
    with open(f"{W}/{name}.txt", "w", encoding="utf-8") as f:
        f.write(text + "\n")
print("wrote", len(P), "prompts to", W)
